<?php require_once 'bootstrap.php';$u=require_login();$st=db()->prepare('SELECT * FROM user_preferences WHERE user_sic_id=?');$st->execute([$u['sic_id']]);$p=$st->fetch()?:['leaderboard_opt_in'=>0,'leaderboard_display'=>'NICKNAME','nickname'=>'','voice_enabled'=>1,'reduced_motion'=>0,'locale'=>'it'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$opt=isset($_POST['leaderboard_opt_in'])?1:0;$display=in_array($_POST['leaderboard_display']??'NICKNAME',['NAME','NICKNAME','ANONYMOUS','HIDDEN'],true)?$_POST['leaderboard_display']:'NICKNAME';$nick=trim($_POST['nickname']??'');$voice=isset($_POST['voice_enabled'])?1:0;$motion=isset($_POST['reduced_motion'])?1:0;$loc=preg_replace('/[^a-z-]/','',strtolower($_POST['locale']??'it'));db()->prepare('INSERT INTO user_preferences(user_sic_id,leaderboard_opt_in,leaderboard_display,nickname,voice_enabled,reduced_motion,locale) VALUES(?,?,?,?,?,?,?) ON CONFLICT(user_sic_id) DO UPDATE SET leaderboard_opt_in=excluded.leaderboard_opt_in,leaderboard_display=excluded.leaderboard_display,nickname=excluded.nickname,voice_enabled=excluded.voice_enabled,reduced_motion=excluded.reduced_motion,locale=excluded.locale,updated_at=CURRENT_TIMESTAMP')->execute([$u['sic_id'],$opt,$display,$nick,$voice,$motion,$loc]);db()->prepare('INSERT INTO consent_log(sic_id,user_sic_id,consent_code,value,version) VALUES(?,?,?,?,?)')->execute([sic_id(),$u['sic_id'],'SOBRIETY_LEADERBOARD',$opt,'1.0']);audit($u['sic_id'],'PRIVACY_PREFERENCES',$u['sic_id'],['leaderboard'=>$opt,'display'=>$display]);$msg='Preferenze salvate.';$p=['leaderboard_opt_in'=>$opt,'leaderboard_display'=>$display,'nickname'=>$nick,'voice_enabled'=>$voice,'reduced_motion'=>$motion,'locale'=>$loc];}$pageTitle='Privacy Center';require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Private by default</span><h1>Privacy Center</h1><p>Decidi cosa condividere. La sobrietà non entra mai in una classifica pubblica senza consenso esplicito.</p></div></section><?php if($msg):?><div class="success"><?=h($msg)?></div><?php endif;?><section class="card"><form method="post" class="stack"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><label><input type="checkbox" name="leaderboard_opt_in" <?=$p['leaderboard_opt_in']?'checked':''?>> Partecipa volontariamente alla leaderboard sobrietà</label><label>Come apparire<select name="leaderboard_display"><?php foreach(['NICKNAME'=>'Nickname','ANONYMOUS'=>'Anonimo','NAME'=>'Nome','HIDDEN'=>'Nascosto'] as $v=>$l):?><option value="<?=$v?>" <?=$p['leaderboard_display']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Nickname<input name="nickname" value="<?=h($p['nickname'])?>"></label><label><input type="checkbox" name="voice_enabled" <?=$p['voice_enabled']?'checked':''?>> Funzioni vocali</label><label><input type="checkbox" name="reduced_motion" <?=$p['reduced_motion']?'checked':''?>> Riduci animazioni/rotazione globo</label><button class="btn primary">Salva preferenze</button></form></section><?php require '_footer.php';?>